import { result } from "@dynatrace-sdk/automation-utils";

const COMPONENT_MODE = {
  saas: "sprint",
  oneagent: "sprint",
  activegate: "sprint",
  operator: "semver",
  edgeconnect: "semver"
};

function unavailableRow(component, observedAt, message, sourceType = "pending_source_validation") {
  return {
    component,
    observed_version: "",
    running_count: "0",
    source_type: sourceType,
    source_status: "unavailable",
    observed_at: observedAt,
    collection_message: message
  };
}

function parseVersionParts(version, mode) {
  const text = String(version || "").trim();
  if (!text) return null;

  if (mode === "sprint") {
    const m = text.match(/^1\.(\d+)(?:\.|$)/);
    if (!m) return null;
    return [1, Number(m[1]), 0];
  }

  const m = text.match(/^(\d+)\.(\d+)\.(\d+)(?:\.|-|$)/);
  if (!m) return null;
  return [Number(m[1]), Number(m[2]), Number(m[3])];
}

function compareVersions(a, b, mode) {
  const pa = parseVersionParts(a, mode);
  const pb = parseVersionParts(b, mode);
  if (!pa && !pb) return 0;
  if (!pa) return -1;
  if (!pb) return 1;
  for (let i = 0; i < 3; i += 1) {
    if (pa[i] !== pb[i]) return pa[i] - pb[i];
  }
  return 0;
}

function normalizeOneAgent(records, observedAt) {
  const out = [];
  const rows = Array.isArray(records) ? records : [];
  for (const r of rows) {
    const version = String(r.installerVersion || r.oneagent_version || "").trim();
    const count = r.hosts ?? r.count ?? 0;
    if (!version) continue;
    out.push({
      component: "oneagent",
      observed_version: version,
      running_count: String(count),
      source_type: "dql_host_installerVersion",
      source_status: "current",
      observed_at: observedAt,
      collection_message: ""
    });
  }
  if (!out.length) {
    out.push(unavailableRow("oneagent", observedAt, "No OneAgent runtime rows returned", "dql_host_installerVersion"));
  }
  return out;
}

function rowsFromTaskPayload(taskResult, component, observedAt) {
  const rows = Array.isArray(taskResult?.runtime_rows) ? taskResult.runtime_rows : [];
  if (rows.length) return rows;
  return [unavailableRow(component, observedAt, "No runtime payload from " + component + " collector")];
}

function normalizeDistributionRows({ component, records, versionField, countField, observedAt, sourceType }) {
  const out = [];
  const rows = Array.isArray(records) ? records : [];
  for (const r of rows) {
    const version = String(r?.[versionField] || "").trim();
    const count = r?.[countField] ?? 0;
    if (!version) continue;
    out.push({
      component,
      observed_version: version,
      running_count: String(count),
      source_type: sourceType,
      source_status: "current",
      observed_at: observedAt,
      collection_message: ""
    });
  }

  if (!out.length) {
    return [unavailableRow(component, observedAt, "No " + component + " runtime rows returned", sourceType)];
  }

  return out;
}

function normalizeOperatorRows(records, observedAt) {
  const rows = Array.isArray(records) ? records : [];
  const clusterCountRaw = rows[0]?.cluster_count ?? 0;
  const clusterCount = Number(clusterCountRaw || 0);

  if (!Number.isFinite(clusterCount) || clusterCount <= 0) {
    return [{
      component: "operator",
      observed_version: "",
      running_count: "0",
      source_type: "dql_kubernetes_cluster_inventory",
      source_status: "not_configured",
      observed_at: observedAt,
      collection_message: "No Kubernetes clusters detected in tenant"
    }];
  }

  return [{
    component: "operator",
    observed_version: "",
    running_count: String(clusterCount),
    source_type: "dql_kubernetes_cluster_inventory",
    source_status: "partial",
    observed_at: observedAt,
    collection_message: "Kubernetes clusters detected; operator runtime version source not yet implemented"
  }];
}

function extractLegacyAiSummary(aiResult) {
  const raw = aiResult?.answer || aiResult?.response || aiResult?.text || aiResult?.output || "";
  const text = String(raw || "").trim();
  if (!text) {
    return { breaking_changes_summary: "", highlights_summary: "" };
  }

  const compact = text.length > 1200 ? (text.slice(0, 1197) + "...") : text;
  const breakingMatch = compact.match(/BREAKING:\s*([\s\S]*?)(?:HIGHLIGHTS:|$)/i);
  const highlightsMatch = compact.match(/HIGHLIGHTS:\s*([\s\S]*)$/i);

  function normalizeSection(value) {
    return String(value || "")
      .split("\n")
      .map((line) => line.trim())
      .filter((line) => line && line !== "-")
      .join("\n");
  }

  const breaking = normalizeSection(breakingMatch?.[1]);
  const highlights = normalizeSection(highlightsMatch?.[1]);

  return {
    breaking_changes_summary: breaking || compact,
    highlights_summary: highlights || compact
  };
}

function parsePerVersionAiMap(aiResult) {
  const out = new Map();
  const candidates = [];
  if (typeof aiResult?.per_version_json === "string") candidates.push(aiResult.per_version_json);
  if (typeof aiResult?.answer === "string") candidates.push(aiResult.answer);
  if (typeof aiResult?.response === "string") candidates.push(aiResult.response);

  for (const text of candidates) {
    const trimmed = String(text || "").trim();
    if (!trimmed) continue;

    let parsed = null;
    try {
      parsed = JSON.parse(trimmed);
    } catch (e) {
      const firstBracket = trimmed.indexOf("[");
      const lastBracket = trimmed.lastIndexOf("]");
      if (firstBracket >= 0 && lastBracket > firstBracket) {
        const snippet = trimmed.slice(firstBracket, lastBracket + 1);
        try {
          parsed = JSON.parse(snippet);
        } catch (ignored) {
          parsed = null;
        }
      }
    }

    if (!Array.isArray(parsed)) continue;

    for (const row of parsed) {
      const component = String(row?.component || "").trim();
      const releasedVersion = String(row?.released_version || row?.version || "").trim();
      if (!component || !releasedVersion) continue;
      const key = component + "|" + releasedVersion;
      out.set(key, {
        breaking_changes_summary: String(row?.breaking_changes_summary || row?.breaking || "").trim(),
        highlights_summary: String(row?.highlights_summary || row?.highlights || "").trim(),
        risk_markdown: String(row?.risk_markdown || "").trim(),
        highlights_markdown: String(row?.highlights_markdown || "").trim(),
        risk_items_json: toJsonArrayString(row?.risk_items),
        highlights_items_json: toJsonArrayString(row?.highlight_items),
        breaking_items_json: toJsonArrayString(row?.breaking_items),
        coming_items_json: toJsonArrayString(row?.coming_items),
        value_summary: String(row?.value_summary || row?.highlights_summary || row?.highlights || "").trim(),
        admin_actions_summary: String(row?.admin_actions_summary || "").trim()
      });
    }

    if (out.size > 0) break;
  }

  return out;
}

function buildRunningVersionMap(runtimeRows) {
  const byComponent = {};
  for (const row of runtimeRows) {
    const component = String(row.component || "").trim();
    if (!component) continue;
    if (String(row.source_status || "") !== "current") continue;
    const version = String(row.observed_version || "").trim();
    if (!version) continue;

    const mode = COMPONENT_MODE[component] || "semver";
    const current = byComponent[component];
    if (!current || compareVersions(version, current, mode) > 0) {
      byComponent[component] = version;
    }
  }
  return byComponent;
}

function ensureKeySet(rows) {
  const set = new Set();
  for (const row of rows) {
    const key = String(row.component || "") + "|" + String(row.released_version || "") + "|" + String(row.is_next_planned || "false");
    set.add(key);
  }
  return set;
}

function fallbackSummary(kind, releaseUrl, parserStatus) {
  const url = String(releaseUrl || "").trim() || "not available";
  const status = String(parserStatus || "unknown");
  if (kind === "breaking") {
    return "AI unavailable, review release_url: " + url + " (parser_status=" + status + ")";
  }
  return "AI unavailable, review release_url for feature updates: " + url + " (parser_status=" + status + ")";
}

function normalizeTextField(value, maxLen = 1200) {
  const compact = String(value || "")
    .replace(/[\n\r\t]+/g, " ")
    .replace(/\s+/g, " ")
    .trim();
  if (!compact) return "";
  if (compact.length <= maxLen) return compact;
  return compact.slice(0, maxLen - 3) + "...";
}

function normalizeAiItems(rawItems, maxItems = 8) {
  const source = Array.isArray(rawItems) ? rawItems : [];
  const out = [];
  for (const item of source) {
    if (out.length >= maxItems) break;
    if (item === null || item === undefined) continue;

    if (typeof item === "string") {
      const text = normalizeTextField(item, 220);
      if (!text) continue;
      out.push(text);
      continue;
    }

    const severity = normalizeTextField(item?.severity || "", 32);
    const category = normalizeTextField(item?.category || "", 64);
    const text = normalizeTextField(item?.text || item?.summary || item?.detail || "", 220);
    if (!text) continue;

    const prefix = [severity, category].filter(Boolean).join("/");
    out.push(prefix ? `${prefix}: ${text}` : text);
  }
  return out;
}

function markdownFromItems(items) {
  const normalized = normalizeAiItems(items, 8);
  if (!normalized.length) return "";
  return normalized.map((item, idx) => `${idx + 1}. ${item}`).join(" • ");
}

function toJsonArrayString(items) {
  const normalized = normalizeAiItems(items, 8);
  if (!normalized.length) return "[]";
  return JSON.stringify(normalized);
}

function releaseLinkMarkdown(url) {
  const releaseUrl = String(url || "").trim();
  if (!releaseUrl) return "";
  return `[Open release](${releaseUrl})`;
}

function summarizeArrayJson(rawJson, fallbackText) {
  const items = safeParseArrayJson(rawJson);
  if (items.length) return items.join(" • ");
  return normalizeTextField(fallbackText || "", 1200);
}

function buildNarrativeFields(row) {
  const breakingSummary = summarizeArrayJson(row.breaking_items_json, row.breaking_changes_summary || row.parsed_breaking_changes);
  const comingSummary = summarizeArrayJson(row.coming_items_json, row.parsed_feature_sections || row.raw_release_summary);
  const valueSummary = normalizeTextField(row.value_summary || row.highlights_summary || row.parsed_feature_updates || row.parsed_feature_sections, 1200);
  const actionSummary = normalizeTextField(row.admin_actions_summary || row.action_hint || "Review release notes and validate in staging", 900);

  const breakingMarkdown = normalizeTextField(breakingSummary || fallbackSummary("breaking", row.release_url, row.parser_status), 1400);
  const comingMarkdown = normalizeTextField(comingSummary || valueSummary || fallbackSummary("highlights", row.release_url, row.parser_status), 1400);
  const valueMarkdown = normalizeTextField(valueSummary || "Value summary unavailable; review release notes.", 1400);
  const actionMarkdown = normalizeTextField(actionSummary, 900);

  const releaseLink = releaseLinkMarkdown(row.release_url) || row.release_url || "";
  const sectionedSummary = [
    "Breaking to plan for: " + breakingMarkdown,
    "What is coming: " + comingMarkdown,
    "Why this matters: " + valueMarkdown,
    "What to do now: " + actionMarkdown,
    "Release: " + releaseLink
  ].join(" || ");

  return {
    breaking_markdown: breakingMarkdown,
    coming_markdown: comingMarkdown,
    value_markdown: valueMarkdown,
    action_markdown: actionMarkdown,
    summary_markdown: sectionedSummary
  };
}

function safeParseArrayJson(raw) {
  try {
    const parsed = JSON.parse(String(raw || "[]"));
    return Array.isArray(parsed) ? parsed : [];
  } catch (e) {
    return [];
  }
}

function deriveRiskPriority(riskItemsJson, riskText) {
  const haystack = [
    ...safeParseArrayJson(riskItemsJson).map((v) => String(v || "")),
    String(riskText || "")
  ].join(" ").toLowerCase();

  if (!haystack.trim() || haystack.trim() === "-") return "🟢 none";
  if (haystack.includes("critical") || haystack.includes("breaking") || haystack.includes("high")) return "🔴 high";
  if (haystack.includes("medium") || haystack.includes("warning") || haystack.includes("deprecated")) return "🟠 medium";
  return "🟡 review";
}

function deriveHighlightFocus(highlightsItemsJson, highlightsText) {
  const items = safeParseArrayJson(highlightsItemsJson)
    .map((v) => normalizeTextField(String(v || ""), 160))
    .filter(Boolean)
    .slice(0, 3);

  if (items.length > 0) return items.join(" | ");

  const fallback = normalizeTextField(highlightsText, 220);
  return fallback || "No notable highlights listed";
}

function deriveActionHint(row, riskPriority) {
  if (String(row.is_newer_than_running || "false") === "true") {
    if (riskPriority.startsWith("🔴")) return "Plan upgrade review now; validate compatibility before rollout";
    if (riskPriority.startsWith("🟠")) return "Queue upgrade validation this sprint";
    return "Schedule upgrade when maintenance window permits";
  }

  const running = String(row.running_version || "").trim();
  if (!running || running === "-") return "Runtime version unknown; verify source health and collector coverage";

  if (riskPriority.startsWith("🔴")) return "Monitor release notes and create rollback-aware test checklist";
  return "No immediate action required";
}

function applyDeterministicSummaries(row) {
  const shouldRequire = row.is_latest === "true" || row.is_newer_than_running === "true";
  const normalized = {
    ...row,
    parser_status: row.parser_status || "not_parsed",
    parsed_breaking_changes: normalizeTextField(row.parsed_breaking_changes, 1000),
    parsed_breaking_changes_all: normalizeTextField(row.parsed_breaking_changes_all, 12000),
    parsed_feature_updates: normalizeTextField(row.parsed_feature_updates, 1000),
    parsed_feature_sections: normalizeTextField(row.parsed_feature_sections, 1500),
    raw_release_summary: normalizeTextField(row.raw_release_summary, 1000),
    feature_updates_count: normalizeTextField(row.feature_updates_count, 16),
    breaking_changes_count: normalizeTextField(row.breaking_changes_count, 16),
    fixes_maintenance_count: normalizeTextField(row.fixes_maintenance_count, 16),
    oneagent_oldest_supported_standard: normalizeTextField(row.oneagent_oldest_supported_standard, 32),
    oneagent_oldest_supported_ess: normalizeTextField(row.oneagent_oldest_supported_ess, 32)
  };

  if (!shouldRequire) {
    normalized.breaking_changes_summary = normalizeTextField(normalized.breaking_changes_summary, 1200);
    normalized.highlights_summary = normalizeTextField(normalized.highlights_summary, 1200);
    normalized.risk_markdown = normalizeTextField(normalized.risk_markdown, 1500);
    normalized.highlights_markdown = normalizeTextField(normalized.highlights_markdown, 1500);
    normalized.risk_items_json = normalizeTextField(normalized.risk_items_json || "[]", 1800);
    normalized.highlights_items_json = normalizeTextField(normalized.highlights_items_json || "[]", 1800);
    normalized.release_link_markdown = normalizeTextField(normalized.release_link_markdown, 500);
    normalized.risk_priority = normalizeTextField(normalized.risk_priority, 32) || deriveRiskPriority(normalized.risk_items_json, normalized.risk_markdown || normalized.breaking_changes_summary);
    normalized.highlight_focus = normalizeTextField(normalized.highlight_focus, 400) || deriveHighlightFocus(normalized.highlights_items_json, normalized.highlights_markdown || normalized.highlights_summary);
    normalized.action_hint = normalizeTextField(normalized.action_hint, 220) || deriveActionHint(normalized, normalized.risk_priority);
    return normalized;
  }

  const breaking = normalizeTextField(normalized.breaking_changes_summary, 1200);
  const highlights = normalizeTextField(normalized.highlights_summary, 1200);

  normalized.breaking_changes_summary = breaking || normalized.parsed_breaking_changes || fallbackSummary("breaking", normalized.release_url, normalized.parser_status);
  normalized.highlights_summary = highlights || normalized.parsed_feature_updates || normalized.parsed_feature_sections || fallbackSummary("highlights", normalized.release_url, normalized.parser_status);
  normalized.risk_markdown = normalizeTextField(normalized.risk_markdown, 1500) || normalized.breaking_changes_summary;
  normalized.highlights_markdown = normalizeTextField(normalized.highlights_markdown, 1500) || normalized.highlights_summary;
  normalized.risk_items_json = normalizeTextField(normalized.risk_items_json || "[]", 1800);
  normalized.highlights_items_json = normalizeTextField(normalized.highlights_items_json || "[]", 1800);
  normalized.release_link_markdown = normalizeTextField(normalized.release_link_markdown, 500) || releaseLinkMarkdown(normalized.release_url);
  normalized.risk_priority = normalizeTextField(normalized.risk_priority, 32) || deriveRiskPriority(normalized.risk_items_json, normalized.risk_markdown || normalized.breaking_changes_summary);
  normalized.highlight_focus = normalizeTextField(normalized.highlight_focus, 400) || deriveHighlightFocus(normalized.highlights_items_json, normalized.highlights_markdown || normalized.highlights_summary);
  normalized.action_hint = normalizeTextField(normalized.action_hint, 220) || deriveActionHint(normalized, normalized.risk_priority);

  const narrative = buildNarrativeFields(normalized);
  normalized.breaking_markdown = normalizeTextField(normalized.breaking_markdown, 1600) || narrative.breaking_markdown;
  normalized.coming_markdown = normalizeTextField(normalized.coming_markdown, 1600) || narrative.coming_markdown;
  normalized.value_markdown = normalizeTextField(normalized.value_markdown, 1600) || narrative.value_markdown;
  normalized.action_markdown = normalizeTextField(normalized.action_markdown, 1000) || narrative.action_markdown;
  normalized.summary_markdown = normalizeTextField(normalized.summary_markdown, 2000) || narrative.summary_markdown;

  return normalized;
}

export default async function () {
  const releaseData = await result("collect_release_indexes");
  const saasData = await result("collect_saas_current_version");
  const oneagentData = await result("collect_oneagent_runtime_distribution");
  const activegateData = await result("collect_activegate_runtime_distribution");
  const operatorData = await result("collect_operator_runtime_distribution");
  const edgeconnectData = await result("collect_edgeconnect_runtime_distribution");
  let oneagentBaseline = {};
  try {
    oneagentBaseline = await result("oneagent_collect_release_baseline");
  } catch (e) {
    oneagentBaseline = {};
  }
  const observedAt = new Date().toISOString();

  let aiData = {};
  try {
    aiData = await result("ai_summarize_release_notes");
  } catch (e) {
    aiData = {};
  }

  const legacyAiSummary = extractLegacyAiSummary(aiData);
  const perVersionAiMap = parsePerVersionAiMap(aiData);

  const oneagentRows = normalizeOneAgent(oneagentData?.records || oneagentData?.result?.records || [], observedAt);
  const saasRows = rowsFromTaskPayload(saasData, "saas", observedAt);
  const activegateRows = normalizeDistributionRows({
    component: "activegate",
    records: activegateData?.records || activegateData?.result?.records || [],
    versionField: "activegate_version",
    countField: "running_count",
    observedAt,
    sourceType: "logs_activegate_started_parse"
  });
  const operatorRows = normalizeOperatorRows(operatorData?.records || operatorData?.result?.records || [], observedAt);
  const edgeconnectRows = rowsFromTaskPayload(edgeconnectData, "edgeconnect", observedAt);

  const runtime_rows = [
    ...saasRows,
    ...oneagentRows,
    ...activegateRows,
    ...operatorRows,
    ...edgeconnectRows
  ];

  const runningVersionByComponent = buildRunningVersionMap(runtime_rows);
  const baseReleaseRows = Array.isArray(releaseData?.release_rows) ? releaseData.release_rows : [];
  const releaseCatalog = releaseData?.release_catalog && typeof releaseData.release_catalog === "object" ? releaseData.release_catalog : {};
  const releaseDetails = releaseData?.release_details && typeof releaseData.release_details === "object" ? releaseData.release_details : {};

  const newerRankByVersion = new Map();
  for (const component of Object.keys(releaseCatalog)) {
    const mode = COMPONENT_MODE[component] || "semver";
    const runningVersion = runningVersionByComponent[component] || "";
    const catalogRows = Array.isArray(releaseCatalog[component]) ? releaseCatalog[component] : [];
    if (!runningVersion) continue;

    const newer = catalogRows
      .filter((row) => compareVersions(row.version, runningVersion, mode) > 0)
      .sort((a, b) => compareVersions(b.version, a.version, mode));

    let rank = 1;
    for (const row of newer) {
      newerRankByVersion.set(component + "|" + String(row.version || ""), rank);
      rank += 1;
    }
  }

  const release_rows = baseReleaseRows.map((r) => {
    const versionKey = String(r.component || "") + "|" + String(r.released_version || "");
    const ai = perVersionAiMap.get(versionKey);
    const details = releaseDetails[versionKey] || {};
    const runningVersion = runningVersionByComponent[r.component] || "";
    const rank = newerRankByVersion.get(versionKey);

    return applyDeterministicSummaries({
      ...r,
      parser_status: r.parser_status || details.parser_status || "not_parsed",
      parsed_breaking_changes: r.parsed_breaking_changes || details.parsed_breaking_changes || "",
      parsed_breaking_changes_all: r.parsed_breaking_changes_all || details.parsed_breaking_changes_all || "",
      parsed_feature_updates: r.parsed_feature_updates || details.parsed_feature_updates || "",
      parsed_feature_sections: r.parsed_feature_sections || details.parsed_feature_sections || "",
      raw_release_summary: r.raw_release_summary || details.raw_release_summary || "",
      feature_updates_count: r.feature_updates_count || details.feature_updates_count || "",
      breaking_changes_count: r.breaking_changes_count || details.breaking_changes_count || "",
      fixes_maintenance_count: r.fixes_maintenance_count || details.fixes_maintenance_count || "",
      oneagent_oldest_supported_standard: r.component === "oneagent" ? String(oneagentBaseline?.oldest_supported_standard || "") : "",
      oneagent_oldest_supported_ess: r.component === "oneagent" ? String(oneagentBaseline?.oldest_supported_ess || "") : "",
      breaking_changes_summary: ai?.breaking_changes_summary || (r.is_latest === "true" ? legacyAiSummary.breaking_changes_summary : ""),
      highlights_summary: ai?.highlights_summary || (r.is_latest === "true" ? legacyAiSummary.highlights_summary : ""),
      risk_markdown: ai?.risk_markdown || markdownFromItems(JSON.parse(ai?.risk_items_json || "[]")) || "",
      highlights_markdown: ai?.highlights_markdown || markdownFromItems(JSON.parse(ai?.highlights_items_json || "[]")) || "",
      risk_items_json: ai?.risk_items_json || "[]",
      highlights_items_json: ai?.highlights_items_json || "[]",
      release_link_markdown: releaseLinkMarkdown(r.release_url),
      is_newer_than_running: rank ? "true" : "false",
      newer_than_running_rank: rank ? String(rank) : "",
      running_version: runningVersion
    });
  });

  const existing = ensureKeySet(release_rows);

  for (const component of Object.keys(releaseCatalog)) {
    const mode = COMPONENT_MODE[component] || "semver";
    const runningVersion = runningVersionByComponent[component] || "";
    const catalogRows = Array.isArray(releaseCatalog[component]) ? releaseCatalog[component] : [];

    if (!runningVersion) continue;

    const newer = catalogRows
      .filter((row) => compareVersions(row.version, runningVersion, mode) > 0)
      .sort((a, b) => compareVersions(b.version, a.version, mode));

    let rank = 1;
    for (const row of newer) {
      const key = component + "|" + String(row.version || "") + "|false";
      const aiKey = component + "|" + String(row.version || "");
      const ai = perVersionAiMap.get(aiKey);
      const details = releaseDetails[aiKey] || {};

      if (!existing.has(key)) {
        release_rows.push(applyDeterministicSummaries({
          component,
          released_version: String(row.version || ""),
          release_status: "current",
          rollout_start_date: r.rollout_start_date || details.rollout_start_date || "",
          is_latest: "false",
          is_next_planned: "false",
          release_url: String(row.release_url || ""),
          index_url: String(row.release_url || ""),
          fetched_at: releaseData?.fetched_at || observedAt,
          parser_status: details.parser_status || "not_parsed",
          parsed_breaking_changes: details.parsed_breaking_changes || "",
          parsed_breaking_changes_all: details.parsed_breaking_changes_all || "",
          parsed_feature_updates: details.parsed_feature_updates || "",
          parsed_feature_sections: details.parsed_feature_sections || "",
          raw_release_summary: details.raw_release_summary || "",
          feature_updates_count: details.feature_updates_count || "",
          breaking_changes_count: details.breaking_changes_count || "",
          fixes_maintenance_count: details.fixes_maintenance_count || "",
          oneagent_oldest_supported_standard: component === "oneagent" ? String(oneagentBaseline?.oldest_supported_standard || "") : "",
          oneagent_oldest_supported_ess: component === "oneagent" ? String(oneagentBaseline?.oldest_supported_ess || "") : "",
          breaking_changes_summary: ai?.breaking_changes_summary || "",
          highlights_summary: ai?.highlights_summary || "",
          risk_markdown: ai?.risk_markdown || markdownFromItems(JSON.parse(ai?.risk_items_json || "[]")) || "",
          highlights_markdown: ai?.highlights_markdown || markdownFromItems(JSON.parse(ai?.highlights_items_json || "[]")) || "",
          risk_items_json: ai?.risk_items_json || "[]",
          highlights_items_json: ai?.highlights_items_json || "[]",
          release_link_markdown: releaseLinkMarkdown(row.release_url),
          is_newer_than_running: "true",
          newer_than_running_rank: String(rank),
          running_version: runningVersion
        }));
        existing.add(key);
      }
      rank += 1;
    }
  }

  return {
    release_rows,
    runtime_rows,
    observed_at: observedAt,
    running_versions: runningVersionByComponent,
    release_catalog_count: Object.values(releaseCatalog).reduce((n, rows) => n + (Array.isArray(rows) ? rows.length : 0), 0)
  };
}

import { result } from "@dynatrace-sdk/automation-utils";

function norm(value) {
  const text = String(value || "").trim();
  return text && text !== "-" ? text : "Unknown";
}

function asLines(value) {
  const raw = String(value || "").trim();
  if (!raw || raw === "-") return ["- No explicit entries published"];
  const parts = raw.split(" || ").map((v) => v.trim()).filter(Boolean);
  if (!parts.length) return ["- No explicit entries published"];
  return parts.map((v) => "- " + v);
}

function parseItems(value) {
  const raw = String(value || "").trim();
  if (!raw || raw === "-") return [];
  return raw.split(" || ").map((v) => v.trim()).filter(Boolean);
}

function listBlock(items, emptyText) {
  const values = Array.isArray(items) ? items : [];
  if (!values.length) return ["- " + emptyText];
  return values.map((item) => "- " + item);
}

function toCount(rowValue, derivedCount) {
  const text = String(rowValue || "").trim();
  if (/^\d+$/.test(text)) return Number(text);
  return Number.isFinite(derivedCount) ? derivedCount : 0;
}

function riskBadge(breakingCount) {
  if (breakingCount >= 5) return "🔴 High change risk";
  if (breakingCount >= 1) return "🟡 Review required";
  return "🟢 Low immediate risk";
}

function selectRow(rows, component, rowKind) {
  const filtered = rows.filter((r) => r.component === component);
  if (rowKind === "current") return filtered.find((r) => String(r.is_latest) === "true") || null;
  return filtered.find((r) => String(r.is_next_planned) === "true") || null;
}

function cardTitle(component, rowKind) {
  const suffix = rowKind === "current" ? "Current" : "Next Planned";
  return "## " + component + " - " + suffix;
}

function buildCard(row, component, rowKind, supportFloor) {
  if (!row) {
    return cardTitle(component, rowKind) + "\n\nNo release row was produced in this workflow run.";
  }

  const releaseVersion = norm(row.released_version);
  const runningVersion = norm(row.running_version);
  const releaseUrl = norm(row.release_url);
  const featureItems = parseItems(row.parsed_feature_items || row.parsed_feature_sections);
  const breakingItems = parseItems(row.parsed_breaking_items || row.parsed_breaking_changes_all || row.parsed_breaking_changes);
  const fixesItems = parseItems(row.parsed_fixes_items || row.parsed_fixes_maintenance);

  const featureCount = toCount(row.feature_updates_count, featureItems.length);
  const breakingCount = toCount(row.breaking_changes_count, breakingItems.length);
  const fixesCount = toCount(row.fixes_maintenance_count, fixesItems.length);

  const status = riskBadge(breakingCount);
  const rolloutDate = norm(row.rollout_start_date);
  const action = norm(row.action_hint);

  const lines = [
    cardTitle(component, rowKind),
    "",
    "### " + status,
    "",
    "- **Released version:** " + releaseVersion,
    "- **Running version:** " + runningVersion,
    "- **Feature updates count:** " + featureCount,
    "- **Breaking changes count:** " + breakingCount,
    "- **Fixes and maintenance count:** " + fixesCount,
    "- **Rollout start date:** " + rolloutDate,
    "- **Release link:** [Open release](" + releaseUrl + ")",
    "",
    "### Feature updates",
    ...listBlock(featureItems, "No explicit feature updates section found on source page."),
    "",
    "### Breaking changes",
    ...listBlock(breakingItems, "No explicit breaking changes section found on source page."),
    "",
    "### Fixes and maintenance",
    ...listBlock(fixesItems, "No explicit fixes and maintenance section found on source page."),
    "",
    "### Action plan",
    "- " + action
  ];

  if (component === "OneAgent") {
    lines.splice(10, 0,
      "- OneAgent oldest supported (Standard): " + norm(supportFloor.standard),
      "- OneAgent oldest supported (ESS): " + norm(supportFloor.ess)
    );
  }

  return lines.join("\n");
}

export default async function () {
  const payload = await result("build_lookup_payloads");
  const rows = Array.isArray(payload?.release_rows) ? payload.release_rows : [];
  const observedAt = String(payload?.observed_at || new Date().toISOString());

  const oneagentCurrent = selectRow(rows, "oneagent", "current");
  const supportFloor = {
    standard: oneagentCurrent?.oneagent_oldest_supported_standard || "",
    ess: oneagentCurrent?.oneagent_oldest_supported_ess || ""
  };

  const components = [
    { key: "saas", label: "SaaS", currentTile: "2", plannedTile: "3" },
    { key: "oneagent", label: "OneAgent", currentTile: "4", plannedTile: "5" },
    { key: "activegate", label: "ActiveGate", currentTile: "6", plannedTile: "7" },
    { key: "operator", label: "Operator", currentTile: "8", plannedTile: "9" },
    { key: "edgeconnect", label: "EdgeConnect", currentTile: "10", plannedTile: "11" }
  ];

  const upgradeComponents = rows
    .filter((r) => String(r.is_latest) === "true" && String(r.is_newer_than_running) === "true")
    .map((r) => String(r.component || "").trim())
    .filter(Boolean);

  const tiles = {
    "0": [
      "# Dynatrace Component Release Tracking v8",
      "",
      "## 🟢🟡🔴 Release Risk Legend",
      "- 🟢 Low immediate risk",
      "- 🟡 Review required",
      "- 🔴 High change risk",
      "",
      "**Last updated (UTC):** " + observedAt,
      "**Workflow mode:** markdown-only cards generated by workflow run"
    ].join("\n"),
    "1": [
      "## Global Summary",
      "",
      "- **Components with newer published release than running:** " + upgradeComponents.length,
      "- **Components:** " + (upgradeComponents.length ? upgradeComponents.join(", ") : "None"),
      "- **Card format:** Current and Next Planned per component",
      "- **Data source:** workflow-generated lookups and parsed release notes",
      "- **Parser detail mode:** itemized Features, Breaking changes, and Fixes/Maintenance from each release URL"
    ].join("\n")
  };

  for (const c of components) {
    const current = selectRow(rows, c.key, "current");
    const planned = selectRow(rows, c.key, "planned");
    tiles[c.currentTile] = buildCard(current, c.label, "current", supportFloor);
    tiles[c.plannedTile] = buildCard(planned, c.label, "planned", supportFloor);
  }

  return { observed_at: observedAt, tiles };
}

