import { result } from "@dynatrace-sdk/automation-utils";

async function getText(url) {
  const resp = await fetch(url);
  if (!resp.ok) throw new Error("HTTP " + resp.status + " for " + url);
  return await resp.text();
}

function uniqueBy(items, keyFn) {
  const out = [];
  const seen = new Set();
  for (const item of items) {
    const key = keyFn(item);
    if (seen.has(key)) continue;
    seen.add(key);
    out.push(item);
  }
  return out;
}

function decodeHtmlEntities(text) {
  return String(text || "")
    .replace(/&nbsp;/g, " ")
    .replace(/&amp;/g, "&")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'");
}

function stripTags(html) {
  return decodeHtmlEntities(String(html || "").replace(/<[^>]+>/g, " "));
}

function cleanText(text, maxLen = 600) {
  const compact = stripTags(text)
    .replace(/\s+/g, " ")
    .replace(/[\n\r\t]+/g, " ")
    .replace(/\|/g, "/")
    .trim();

  if (!compact) return "";
  if (compact.length <= maxLen) return compact;
  return compact.slice(0, maxLen - 3) + "...";
}

function parseSprintEntry(url) {
  const m = url.match(/\/sprint-(\d+)/);
  if (!m) return null;
  const sprint = Number(m[1]);
  return { version: "1." + sprint, sort_a: sprint, sort_b: 0, sort_c: 0, url };
}

function parseOperatorEntry(url) {
  const m = url.match(/dto-fix-(\d+)-(\d+)-(\d+)/);
  if (!m) return null;
  return {
    version: String(Number(m[1])) + "." + String(Number(m[2])) + "." + String(Number(m[3])),
    sort_a: Number(m[1]),
    sort_b: Number(m[2]),
    sort_c: Number(m[3]),
    url
  };
}

function parseEdgeconnectEntry(url) {
  const m = url.match(/edgeconnect-release-notes-(\d+)-(\d+)-(\d+)/);
  if (!m) return null;
  return {
    version: String(Number(m[1])) + "." + String(Number(m[2])) + "." + String(Number(m[3])),
    sort_a: Number(m[1]),
    sort_b: Number(m[2]),
    sort_c: Number(m[3]),
    url
  };
}

function parseEntriesFromSitemap(sitemap, component) {
  const regex = new RegExp("<loc>(https://docs\\.dynatrace\\.com/docs/whats-new/" + component.path + "/[^<]+)</loc>", "g");
  const urls = [...sitemap.matchAll(regex)].map((m) => m[1]);

  const parser = component.mode === "sprint" ? parseSprintEntry
    : component.mode === "operator_semver" ? parseOperatorEntry
    : parseEdgeconnectEntry;

  const entries = uniqueBy(urls.map((u) => parser(u)).filter(Boolean), (e) => e.url);
  entries.sort((a, b) => {
    if (b.sort_a !== a.sort_a) return b.sort_a - a.sort_a;
    if (b.sort_b !== a.sort_b) return b.sort_b - a.sort_b;
    return b.sort_c - a.sort_c;
  });
  return entries;
}

function extractHeadingSections(html) {
  const source = String(html || "");
  const sections = [];
  const headingRegex = /<(h[1-6])[^>]*>([\s\S]*?)<\/\1>/gi;

  let match;
  while ((match = headingRegex.exec(source)) !== null) {
    const level = Number(match[1].slice(1));
    const headingText = cleanText(match[2], 180);
    const headingStart = match.index;
    const headingEnd = headingRegex.lastIndex;

    sections.push({ level, headingText, headingStart, headingEnd });
  }

  for (let i = 0; i < sections.length; i += 1) {
    const bodyStart = sections[i].headingEnd;
    let bodyEnd = source.length;
    for (let j = i + 1; j < sections.length; j += 1) {
      if (sections[j].level <= sections[i].level) {
        bodyEnd = sections[j].headingStart;
        break;
      }
    }
    sections[i].body = source.slice(bodyStart, bodyEnd);
  }

  return sections;
}

function extractFeatureSubsections(featureBodyHtml) {
  const body = String(featureBodyHtml || "");
  const out = [];
  const h3Regex = /<h3[^>]*>([\s\S]*?)<\/h3>/gi;
  const matches = [];

  let m;
  while ((m = h3Regex.exec(body)) !== null) {
    matches.push({ title: cleanText(m[1], 140), start: m.index, end: h3Regex.lastIndex });
  }

  if (!matches.length) {
    const summary = cleanText(body, 420);
    if (summary) {
      out.push({
        title: "Feature updates",
        summary
      });
    }
    return out;
  }

  for (let i = 0; i < matches.length; i += 1) {
    const start = matches[i].end;
    const end = i + 1 < matches.length ? matches[i + 1].start : body.length;
    const snippet = cleanText(body.slice(start, end), 260);
    if (snippet) {
      out.push({
        title: matches[i].title || "Feature update",
        summary: snippet
      });
    }
  }

  return out;
}

function extractCount(text, label) {
  const m = String(text || "").match(new RegExp(label + "\\s*:\\s*(\\d+)", "i"));
  return m ? String(Number(m[1])) : "";
}

function extractListItems(html, maxItems = 200) {
  const source = String(html || "");
  const items = [];
  const re = /<li[^>]*>([\s\S]*?)<\/li>/gi;
  let m;
  while ((m = re.exec(source)) !== null) {
    if (items.length >= maxItems) break;
    const item = cleanText(m[1], 800);
    if (item) items.push(item);
  }
  return items;
}

function countMatches(text, re) {
  const source = String(text || "");
  const m = source.match(re);
  return Array.isArray(m) ? m.length : 0;
}

function pickBestSection(sections, testFn) {
  const candidates = (Array.isArray(sections) ? sections : []).filter(testFn);
  if (!candidates.length) return null;

  let best = candidates[0];
  let bestScore = -1;

  for (const section of candidates) {
    const body = String(section?.body || "");
    const score =
      Math.min(body.length, 24000)
      + (countMatches(body, /<h3[^>]*>/gi) * 600)
      + (countMatches(body, /<li[^>]*>/gi) * 450)
      + (/data-testid="heading"/i.test(body) ? 250 : 0);

    if (score > bestScore) {
      best = section;
      bestScore = score;
    }
  }

  return best;
}

function uniqueItems(items, maxItems = 250) {
  const out = [];
  const seen = new Set();
  for (const raw of Array.isArray(items) ? items : []) {
    if (out.length >= maxItems) break;
    const value = cleanText(raw, 800);
    if (!value) continue;
    const key = value.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    out.push(value);
  }
  return out;
}

function sectionItemsFromBody(sectionBody) {
  const h3Titles = extractFeatureSubsections(sectionBody)
    .map((row) => String(row?.title || "").trim())
    .filter((value) => value && !/^(feature updates?|breaking changes?|fixes?\s*(and|&)\s*maintenance)$/i.test(value));
  if (h3Titles.length) return uniqueItems(h3Titles, 250);

  const fromList = extractListItems(sectionBody, 400);
  if (fromList.length) return uniqueItems(fromList, 250);

  const subsectionPairs = extractFeatureSubsections(sectionBody);
  const fromHeadings = subsectionPairs
    .map((row) => row?.title || "")
    .filter((value) => value && !/^(feature updates?|breaking changes?|fixes?\s*(and|&)\s*maintenance)$/i.test(value));
  if (fromHeadings.length) return uniqueItems(fromHeadings, 250);

  const fallback = cleanText(sectionBody, 2000);
  return fallback ? [fallback] : [];
}

function joinItems(items) {
  return uniqueItems(items, 250).join(" || ");
}

function extractRolloutStartDate(html) {
  const text = cleanText(html, 50000);
  const patterns = [
    /rollout\s+start(?:s)?\s+on\s+([A-Za-z]{3,9}\s+\d{1,2},\s+\d{4})(\s*\(planned\))?/i,
    /rollout\s+start(?:s)?\s*[:\-]?\s*([A-Za-z]{3,9}\s+\d{1,2},\s+\d{4})(\s*\(planned\))?/i,
    /release\s+date\s*[:\-]?\s*([A-Za-z]{3,9}\s+\d{1,2},\s+\d{4})(\s*\(planned\))?/i
  ];
  for (const re of patterns) {
    const m = text.match(re);
    if (m) return (String(m[1] || "").trim() + String(m[2] || "")).trim();
  }
  return "";
}

async function parseReleasePage(url) {
  try {
    const html = await getText(url);
    const sections = extractHeadingSections(html);

    const breakingSection = pickBestSection(sections, (s) => /breaking\s*changes?/i.test(s.headingText));
    const featureSection = pickBestSection(sections, (s) => s.level === 2 && /feature\s*updates?/i.test(s.headingText));
    const fixesSection = pickBestSection(sections, (s) =>
      /fixes?\s*(and|&)\s*maintenance|maintenance\s*and\s*fixes?/i.test(s.headingText)
    );

    const parsedBreaking = breakingSection ? cleanText(breakingSection.body, 2000) : "";
    const parsedFeatureUpdates = featureSection ? cleanText(featureSection.body, 1200) : "";
    const parsedFixesMaintenance = fixesSection ? cleanText(fixesSection.body, 1200) : "";

    const featureSubsections = featureSection
      ? extractFeatureSubsections(featureSection.body)
      : [];

    const parsedFeatureSections = featureSubsections
      .map((s) => s.title + ": " + s.summary)
      .join(" || ");

    const rawSummarySource = sections.find((s) => s.level === 2 && /what'?s\s*new|highlights?|overview/i.test(s.headingText))?.body
      || sections[0]?.body
      || html;

    const featureItems = featureSection ? sectionItemsFromBody(featureSection.body) : [];
    const breakingItems = breakingSection ? sectionItemsFromBody(breakingSection.body) : [];
    const fixesItems = fixesSection ? sectionItemsFromBody(fixesSection.body) : [];

    const rolloutStartDate = extractRolloutStartDate(html);

    const rawReleaseSummary = cleanText(rawSummarySource, 1200);
    const fullPageText = cleanText(html, 30000);
    const featureUpdatesCount = featureItems.length > 0
      ? String(featureItems.length)
      : extractCount(fullPageText, "Feature updates");
    const breakingChangesCount = breakingItems.length > 0
      ? String(breakingItems.length)
      : extractCount(fullPageText, "Breaking changes");
    const fixesMaintenanceCount = fixesItems.length > 0
      ? String(fixesItems.length)
      : extractCount(fullPageText, "Fixes and maintenance");

    const parsedBreakingAll = breakingItems.length
      ? joinItems(breakingItems)
      : (breakingSection ? cleanText(breakingSection.body, 12000) : "");

    return {
      parser_status: "success",
      parsed_breaking_changes: parsedBreaking,
      parsed_breaking_changes_all: parsedBreakingAll,
      parsed_feature_updates: parsedFeatureUpdates,
      parsed_feature_sections: parsedFeatureSections,
      parsed_feature_items: joinItems(featureItems),
      parsed_breaking_items: joinItems(breakingItems),
      parsed_fixes_maintenance: parsedFixesMaintenance,
      parsed_fixes_items: joinItems(fixesItems),
      raw_release_summary: rawReleaseSummary,
      feature_updates_count: featureUpdatesCount,
      breaking_changes_count: breakingChangesCount,
      fixes_maintenance_count: fixesMaintenanceCount,
      rollout_start_date: rolloutStartDate
    };
  } catch (error) {
    return {
      parser_status: "unavailable",
      parsed_breaking_changes: "",
      parsed_breaking_changes_all: "",
      parsed_feature_updates: "",
      parsed_feature_sections: "",
      parsed_feature_items: "",
      parsed_breaking_items: "",
      parsed_fixes_maintenance: "",
      parsed_fixes_items: "",
      raw_release_summary: "",
      feature_updates_count: "",
      breaking_changes_count: "",
      fixes_maintenance_count: "",
      rollout_start_date: "",
      parser_error: cleanText(String(error || "unknown parser error"), 220)
    };
  }
}

function sanitizeForPrompt(value) {
  return String(value || "")
    .replace(/[\n\r\t]+/g, " ")
    .replace(/\|/g, "/")
    .trim();
}

export default async function () {
  const ctx = await result("initialize_workflow_context");
  const docsSitemapUrl = String(ctx?.docs_sitemap_url || "").trim() || "https://docs.dynatrace.com/docs/sitemap.xml";
  const parserDepthRaw = Number(ctx?.release_parser_depth ?? 8);
  const parserDepth = Number.isFinite(parserDepthRaw) && parserDepthRaw > 0 ? Math.min(parserDepthRaw, 15) : 8;

  const components = [
    { component: "saas", path: "saas", mode: "sprint", index_url: "https://docs.dynatrace.com/docs/whats-new/saas" },
    { component: "oneagent", path: "oneagent", mode: "sprint", index_url: "https://docs.dynatrace.com/docs/whats-new/oneagent" },
    { component: "activegate", path: "activegate", mode: "sprint", index_url: "https://docs.dynatrace.com/docs/whats-new/activegate" },
    { component: "operator", path: "dynatrace-operator", mode: "operator_semver", index_url: "https://docs.dynatrace.com/docs/whats-new/dynatrace-operator" },
    { component: "edgeconnect", path: "edgeconnect", mode: "edgeconnect_semver", index_url: "https://docs.dynatrace.com/docs/whats-new/edgeconnect" }
  ];

  const fetched_at = new Date().toISOString();
  const sitemap = await getText(docsSitemapUrl);
  const release_rows = [];
  const release_catalog = {};
  const release_details = {};

  for (const c of components) {
    const entries = parseEntriesFromSitemap(sitemap, c);
    release_catalog[c.component] = entries.slice(0, 15).map((e) => ({ version: e.version, release_url: e.url }));

    for (const entry of entries.slice(0, parserDepth)) {
      const details = await parseReleasePage(entry.url);
      release_details[c.component + "|" + entry.version] = details;
    }

    const latest = entries[0];
    const nextPublished = entries[1];

    const latestDetails = latest ? release_details[c.component + "|" + latest.version] : null;
    const nextDetails = nextPublished ? release_details[c.component + "|" + nextPublished.version] : null;

    release_rows.push({
      component: c.component,
      released_version: latest ? latest.version : "",
      release_status: latest ? "current" : "unavailable",
      rollout_start_date: latestDetails?.rollout_start_date || "",
      is_latest: "true",
      is_next_planned: "false",
      release_url: latest ? latest.url : c.index_url,
      index_url: c.index_url,
      fetched_at,
      parser_status: latestDetails?.parser_status || "not_parsed",
      parsed_breaking_changes: latestDetails?.parsed_breaking_changes || "",
      parsed_breaking_changes_all: latestDetails?.parsed_breaking_changes_all || "",
      parsed_feature_updates: latestDetails?.parsed_feature_updates || "",
      parsed_feature_sections: latestDetails?.parsed_feature_sections || "",
      parsed_feature_items: latestDetails?.parsed_feature_items || "",
      parsed_breaking_items: latestDetails?.parsed_breaking_items || "",
      parsed_fixes_maintenance: latestDetails?.parsed_fixes_maintenance || "",
      parsed_fixes_items: latestDetails?.parsed_fixes_items || "",
      raw_release_summary: latestDetails?.raw_release_summary || "",
      feature_updates_count: latestDetails?.feature_updates_count || "",
      breaking_changes_count: latestDetails?.breaking_changes_count || "",
      fixes_maintenance_count: latestDetails?.fixes_maintenance_count || ""
    });

    release_rows.push({
      component: c.component,
      released_version: nextPublished ? nextPublished.version : "Not yet published",
      release_status: nextPublished ? "current" : "not_yet_published",
      rollout_start_date: nextDetails?.rollout_start_date || "",
      is_latest: "false",
      is_next_planned: "true",
      release_url: nextPublished ? nextPublished.url : c.index_url,
      index_url: c.index_url,
      fetched_at,
      parser_status: nextDetails?.parser_status || "not_parsed",
      parsed_breaking_changes: nextDetails?.parsed_breaking_changes || "",
      parsed_breaking_changes_all: nextDetails?.parsed_breaking_changes_all || "",
      parsed_feature_updates: nextDetails?.parsed_feature_updates || "",
      parsed_feature_sections: nextDetails?.parsed_feature_sections || "",
      parsed_feature_items: nextDetails?.parsed_feature_items || "",
      parsed_breaking_items: nextDetails?.parsed_breaking_items || "",
      parsed_fixes_maintenance: nextDetails?.parsed_fixes_maintenance || "",
      parsed_fixes_items: nextDetails?.parsed_fixes_items || "",
      raw_release_summary: nextDetails?.raw_release_summary || "",
      feature_updates_count: nextDetails?.feature_updates_count || "",
      breaking_changes_count: nextDetails?.breaking_changes_count || "",
      fixes_maintenance_count: nextDetails?.fixes_maintenance_count || ""
    });
  }

  const summary_prompt = release_rows
    .filter((r) => r.is_latest === "true")
    .map((r) => r.component + ": " + (r.released_version || "unavailable") + " " + r.release_url)
    .join("\n");

  const ai_summary_prompt = components.map((c) => {
    const lines = (release_catalog[c.component] || []).slice(0, 5).map((entry) => {
      const key = c.component + "|" + entry.version;
      const details = release_details[key] || {};
      return [
        c.component,
        entry.version,
        entry.release_url,
        sanitizeForPrompt(details.parsed_breaking_changes),
        sanitizeForPrompt(details.parsed_feature_updates),
        sanitizeForPrompt(details.parsed_feature_sections),
        sanitizeForPrompt(details.raw_release_summary)
      ].join("|");
    });
    return lines.join("\n");
  }).filter(Boolean).join("\n");

  return {
    fetched_at,
    release_rows,
    release_catalog,
    release_details,
    summary_prompt,
