function readInput(ex, key, fallback) {
  const workflowInput = ex?.input || {};
  const workflowParams = ex?.params || {};
  const value = String(workflowInput[key] ?? workflowParams[key] ?? "").trim();
  return value || fallback;
}

async function resolveToken(id, keyName) {
  const normalized = String(id || "").trim();
  if (!normalized) throw new Error(`${keyName} is empty.`);
  if (!normalized.startsWith("CREDENTIALS_VAULT-")) {
    throw new Error(`${keyName} must be a Credential Vault ID (CREDENTIALS_VAULT-xxxxxxxxxxxxxxxx).`);
  }

  const credentials = await credentialVaultClient.getCredentialsDetails({ id: normalized });
  if (!credentials || !credentials.token) {
    throw new Error(`No token found in vault entry ${normalized}. Ensure the entry type is \"Token\" and the workflow has access.`);
  }
  return credentials.token;
}

function toBaseUrl(envUrl) {
  const env = new URL(String(envUrl || "").trim());
  env.host = env.host.replace(".apps.", ".");
  env.pathname = "";
  env.search = "";
  env.hash = "";
  return env.toString().replace(/\/$/, "");
}

export default async function () {
  const ex = await execution();

  const apiTokenVaultId = readInput(ex, "apiTokenVaultId", "CREDENTIALS_VAULT-152083F2EC7D5E4B");
