  const lookupTimezone = readInput(ex, "lookupTimezone", "UTC");
  const releaseDashboardV7Id = readInput(ex, "releaseDashboardV7Id", "d3487e5d-e1c1-4212-b3b7-b04a68ad207d");

  const parserDepthRaw = Number(readInput(ex, "releaseParserDepth", "8"));
  const releaseParserDepth = Number.isFinite(parserDepthRaw) && parserDepthRaw > 0 ? Math.min(parserDepthRaw, 15) : 8;

  const envUrl = String(getEnvironmentUrl() || "").trim();
  if (!envUrl) throw new Error("getEnvironmentUrl() returned an empty value.");
  const envBaseUrl = toBaseUrl(envUrl);
