  const platformBearerTokenFromVault = platformTokenVaultId ? await resolveToken(platformTokenVaultId, "platformTokenVaultId") : "";
  const platformBearerToken = platformBearerTokenInput || platformBearerTokenFromVault;

  return {
    initialized_at: new Date().toISOString(),
    env_base_url: envBaseUrl,
    app_base_url: appBaseUrl,
    docs_sitemap_url: docsSitemapUrl,
    release_parser_depth: releaseParserDepth,
