async function getText(url) {
  const resp = await fetch(url);
  if (!resp.ok) throw new Error("HTTP " + resp.status + " for " + url);
  return await resp.text();
}

function escapeRegex(value) {
  return String(value || "").replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

function matchVersionNear(label, html) {
  const escaped = escapeRegex(label);
  const re = new RegExp(escaped + "[\\s\\S]{0,500}?(1\\.\\d{3})", "i");
  const m = String(html || "").match(re);
  return m ? m[1] : "";
}

export default async function () {
  const ctx = await result("initialize_workflow_context");
  const docsSitemapUrl = String(ctx?.docs_sitemap_url || "").trim() || "https://docs.dynatrace.com/docs/sitemap.xml";

  const sitemap = await getText(docsSitemapUrl);
  const matches = [...sitemap.matchAll(/oneagent\/sprint-(\d+)/g)].map((m) => Number(m[1]));
  if (!matches.length) throw new Error("No sprint links found in docs sitemap");

  const latestSprint = Math.max(...matches);
  const latestRelease = "1." + latestSprint;
  const sprintUrl = "https://docs.dynatrace.com/docs/whats-new/oneagent/sprint-" + latestSprint;
  const sprintHtml = await getText(sprintUrl);

  const oldestSupportedStandard = matchVersionNear("Standard Support", sprintHtml);
  const oldestSupportedEss = matchVersionNear("Enterprise Success and Support", sprintHtml);
  if (!oldestSupportedStandard && !oldestSupportedEss) {
    throw new Error("Could not parse oldest supported versions table");
  }

  return {
    latest_release: latestRelease,
    oldest_supported_standard: oldestSupportedStandard,
    oldest_supported_ess: oldestSupportedEss,
    fetched_at: new Date().toISOString(),
    source_url: sprintUrl
  };
}

