function csvCell(v) {
  const s = String(v ?? "");
  const lf = String.fromCharCode(10);
  const cr = String.fromCharCode(13);
  const normalized = s.split(",").join(" ").split(lf).join(" ").split(cr).join(" ").trim();
  return normalized === "" ? "-" : normalized;
}

function toCsv(rows, headers) {
  const lines = [headers.join(",")];
  for (const row of rows) lines.push(headers.map((h) => csvCell(row[h])).join(","));
  return lines.join("\n") + "\n";
}

async function uploadLookup({ filePath, lookupField, parsePattern, headers, rows, locale, timezone }) {
  const csv = toCsv(rows, headers);
  const request = {
    filePath,
    lookupField,
    overwrite: true,
    displayName: filePath.split("/").pop(),
    description: "Generated by Version Intelligence Sync",
    skippedRecords: 1,
